  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
      return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4);
  };

  // @coverage-probe
  std::complex<double> FPFMccT_value =
      2.0*std::pow(za(j3,j4),2)*zab2(j5,j3,j4,j2)*zb(j1,j6)
      /(za(j2,j3)*std::pow(t(j2,j3,j4),2))
    + za(j1,j3)/(za(j2,j3)*t(j1,j2,j3)*t(j2,j3,j4))
      *(zab2(j4,j2,j3,j1)*zab2(j5,j3,j4,j2)*zab2(j3,j1,j2,j6)
        /zab2(j1,j2,j3,j4)
        - zb(j1,j2)*za(j3,j4)*za(j4,j5)*zb(j1,j6));

  return FPFMccT_value;
}

